def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    resultado = []
    contador = 1

    for i in range(1, len(texto)):
        if texto[i] == texto[i-1]:
            contador += 1
        else:
            resultado.append(texto[i-1] + str(contador))
            contador = 1

    # Agregar el último grupo
    resultado.append(texto[-1] + str(contador))

    return "".join(resultado)

def iniciales(nombre: str) -> str:
    palabras = nombre.split()
    return ''.join(palabra[0].upper() for palabra in palabras)

def aplanar(datos: list) -> list:
    resultado = []
    for elemento in datos:
        if isinstance(elemento, (list, tuple)):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

import csv
from typing import List, Dict

def parsear_ventas(texto: str) -> List[Dict]:
    # Separar en líneas y eliminar líneas vacías o con solo espacios
    lines = [line.strip() for line in texto.splitlines() if line.strip()]

    if not lines:
        return []

    # Verificar que la cabecera sea exactamente 'fecha,producto,cantidad,precio'
    if lines[0] != 'fecha,producto,cantidad,precio':
        raise ValueError("La cabecera no es la indicada")

    result = []

    for line in lines[1:]:
        # Parsear como CSV (maneja campos con comas dentro de comillas dobles)
        reader = csv.reader([line])
        row = next(reader)

        if len(row) != 4:
            raise ValueError("Una fila no tiene exactamente 4 campos")

        fecha, producto, cantidad_str, precio_str = row

        # Validar cantidad (debe ser entero y no negativa)
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad no es un entero")

        if cantidad < 0:
            raise ValueError("cantidad no puede ser negativa")

        # Validar precio (debe ser número)
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio no es un número")

        result.append({
            'fecha': fecha,
            'producto': producto,
            'cantidad': cantidad,
            'precio': precio
        })

    return result

from datetime import datetime

def parsear_fecha(texto: str) -> str:
    # Eliminar espacios al principio y al final
    texto = texto.strip()

    # Formato 1: AAAA-MM-DD
    try:
        dt = datetime.strptime(texto, "%Y-%m-%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Formato 2: DD/MM/AAAA
    try:
        dt = datetime.strptime(texto, "%d/%m/%Y")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Formato 3: D de MES de AAAA
    month_map = {
        "enero": 1, "febrero": 2, "marzo": 3, "abril": 4,
        "mayo": 5, "junio": 6, "julio": 7, "agosto": 8,
        "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
    }

    try:
        parts = texto.split()
        if len(parts) != 4:
            raise ValueError("Formato incorrecto")

        dia = int(parts[0])
        mes_name = parts[1]
        año = int(parts[2])

        if mes_name not in month_map:
            raise ValueError("Mes no reconocido")

        mes = month_map[mes_name]

        try:
            dt = datetime(year=año, month=mes, day=dia)
            return dt.strftime("%Y-%m-%d")
        except ValueError as e:
            # Fecha inválida (ej. 31/04/2024 o 29/02/2023)
            raise ValueError(f"Fecha no válida: {e}")
    except Exception:
        # Cualquier otro error de parsing se considera formato incorrecto
        raise ValueError("Formato o fecha inválido")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad <= 0:
            raise ValueError("La capacidad debe ser un entero positivo")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Mover al final para marcar como usado recientemente
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if clave in self._datos:
            # La clave ya existe: actualizar y mover al final
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Nueva clave: si la caché está llena, descartar la menos reciente
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
